// Bundles the static-package browser entry (master System Card renderer +
// shopping list + drawer, React included) into a single classic IIFE script,
// then writes it as a TypeScript string-constant module:
//
//   lib/packages/generated/system-card-bundle.ts
//
// The package generator embeds that string as /assets/system-card.js in every
// generated ZIP. Bundling happens at BUILD time (this script runs before
// `next build` — see the package.json build script) so the deployed server
// never needs the esbuild binary at runtime.
//
// Run manually after changing anything under components/system-card-renderer/:
//   corepack pnpm bundle:static-card

import { build } from 'esbuild'
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const appRoot = resolve(here, '..')

const entry = resolve(appRoot, 'components/system-card-renderer/static/entry.tsx')
const outFile = resolve(appRoot, 'lib/packages/generated/system-card-bundle.ts')

const result = await build({
  entryPoints: [entry],
  bundle: true,
  minify: true,
  format: 'iife',
  platform: 'browser',
  target: ['es2019'],
  jsx: 'automatic',
  define: { 'process.env.NODE_ENV': '"production"' },
  write: false,
  logLevel: 'info',
})

const js = result.outputFiles[0].text

const moduleSource =
  '// AUTO-GENERATED by scripts/build-static-card-bundle.mjs — do not edit.\n' +
  '// Regenerate with: corepack pnpm bundle:static-card\n' +
  '// (runs automatically before `next build`)\n' +
  '//\n' +
  '// The browser bundle for static System Card package pages: master v6\n' +
  '// renderer + shopping list + PNG share, React included, IIFE, minified.\n' +
  '/* eslint-disable */\n' +
  `export const SYSTEM_CARD_BUNDLE_JS: string = ${JSON.stringify(js)}\n`

mkdirSync(dirname(outFile), { recursive: true })
writeFileSync(outFile, moduleSource, 'utf8')

console.log(`Wrote ${outFile} (${(js.length / 1024).toFixed(0)} KB bundle)`)
